<?php declare(strict_types=1); $d=$record??$old??[]; ?><div class="card"><div class="form-grid"><div class="form-group full"><label>Event title *</label><input name="title" required value="<?=htmlspecialchars((string)($d['title']??''))?>"></div><div class="form-group"><label>Type</label><input name="event_type" value="<?=htmlspecialchars((string)($d['event_type']??''))?>"></div><div class="form-group"><label>Provider</label><select name="provider_id"><option value="">Independent</option><?php foreach($providers as $p): ?><option value="<?=$p['id']?>" <?=((string)($d['provider_id']??''))===(string)$p['id']?'selected':''?>><?=htmlspecialchars($p['legal_name'])?></option><?php endforeach; ?></select></div><div class="form-group"><label>Start *</label><input type="datetime-local" name="start_at" required value="<?=htmlspecialchars(str_replace(' ','T',(string)($d['start_at']??'')))?>"></div><div class="form-group"><label>End</label><input type="datetime-local" name="end_at" value="<?=htmlspecialchars(str_replace(' ','T',(string)($d['end_at']??'')))?>"></div><div class="form-group"><label>Venue</label><input name="venue" value="<?=htmlspecialchars((string)($d['venue']??''))?>"></div><div class="form-group"><label>City</label><input name="city" value="<?=htmlspecialchars((string)($d['city']??''))?>"></div><div class="form-group"><label>District</label><input name="district" value="<?=htmlspecialchars((string)($d['district']??''))?>"></div><div class="form-group"><label>Organizer</label><input name="organizer_name" value="<?=htmlspecialchars((string)($d['organizer_name']??''))?>"></div><div class="form-group"><label>Phone</label><input name="contact_phone" value="<?=htmlspecialchars((string)($d['contact_phone']??''))?>"></div><div class="form-group"><label>Latitude</label><input name="latitude" value="<?=htmlspecialchars((string)($d['latitude']??''))?>"></div><div class="form-group"><label>Longitude</label><input name="longitude" value="<?=htmlspecialchars((string)($d['longitude']??''))?>"></div><div class="form-group full"><label>Description</label><textarea name="description" rows="5"><?=htmlspecialchars((string)($d['description']??''))?></textarea></div><div class="form-group full"><label>Ticket information</label><input name="ticket_info" value="<?=htmlspecialchars((string)($d['ticket_info']??''))?>"></div><div class="form-group"><label>Status</label><select name="status"><?php foreach(['Draft','Pending','Active','Inactive','Cancelled'] as $v): ?><option value="<?=$v?>" <?=($d['status']??'Draft')===$v?'selected':''?>><?=$v?></option><?php endforeach; ?></select></div><div class="form-group"><label><input type="checkbox" name="featured" value="1" <?=!empty($d['featured'])?'checked':''?>> Featured</label></div></div></div><style>.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.full{grid-column:1/-1}.form-group label{display:block;font-weight:600;margin-bottom:6px}.form-group input,.form-group select,.form-group textarea{width:100%;box-sizing:border-box}@media(max-width:700px){.form-grid{grid-template-columns:1fr}.full{grid-column:auto}}</style>
